&lt;div aria-labelledby=&quot;bs-faq-prod-80-button-2&quot; class=&quot;bs-faq-panel&quot; hidden=&quot;&quot; id=&quot;bs-faq-prod-80-panel-2&quot; role=&quot;region&quot;&gt;
