&lt;div aria-labelledby=&quot;bs-faq-prod-69-button-5&quot; class=&quot;bs-faq-panel&quot; hidden=&quot;&quot; id=&quot;bs-faq-prod-69-panel-5&quot; role=&quot;region&quot;&gt;
