&lt;div aria-labelledby=&quot;bs-faq-hwa-button-3&quot; class=&quot;bs-faq-panel&quot; hidden=&quot;&quot; id=&quot;bs-faq-hwa-panel-3&quot; role=&quot;region&quot;&gt;
