&lt;div aria-labelledby=&quot;bs-faq-op-jp-op16-bst-button-5&quot; class=&quot;bs-faq-panel&quot; hidden=&quot;&quot; id=&quot;bs-faq-op-jp-op16-bst-panel-5&quot; role=&quot;region&quot;&gt;
