&lt;div aria-labelledby=&quot;bs-faq-prod-st33-button-2&quot; class=&quot;bs-faq-panel&quot; hidden=&quot;&quot; id=&quot;bs-faq-prod-st33-panel-2&quot; role=&quot;region&quot;&gt;
