&lt;div aria-labelledby=&quot;bs-faq-prod-acc-007-400-button-2&quot; class=&quot;bs-faq-panel&quot; hidden=&quot;&quot; id=&quot;bs-faq-prod-acc-007-400-panel-2&quot; role=&quot;region&quot;&gt;
